using WeatherRisk.Core.Domain;
using WeatherRisk.Core.Scoring;
using WeatherRisk.Core.Weather;
using WeatherRisk.Data;

var db = Path.Combine(Path.GetTempPath(), "wr-smoke.db");
foreach (var f in new[] { db, db + "-wal", db + "-shm" }) File.Delete(f);
var services = new ServiceCollection().AddLogging();
services.AddSingleton(TimeProvider.System).AddSingleton<IDependencyMetrics, NoMetrics>();
services.AddWeatherRiskPersistence($"Data Source={db}");
services.AddWeatherRiskDataSources(new ConfigurationBuilder().Build());
await using var sp = services.BuildServiceProvider();
await sp.InitializeWeatherRiskDatabaseAsync();
await using var scope = sp.CreateAsyncScope();
var hubs = await scope.ServiceProvider.GetRequiredService<IHubRepository>().GetAllAsync();
var provider = scope.ServiceProvider.GetRequiredService<IHubDataProvider>();
var sw = System.Diagnostics.Stopwatch.StartNew();
var weather = await provider.GetWeatherAsync(hubs);
Console.WriteLine($"weather: {weather.Count} hubs in {sw.ElapsedMilliseconds} ms, window {provider.Window.From}..{provider.Window.To}, freshness: {string.Join(",", weather.Values.Select(w => w.Freshness).Distinct())}");
sw.Restart();
var baselines = await provider.GetBaselinesAsync(hubs);
Console.WriteLine($"baselines: {baselines.Count} counties in {sw.ElapsedMilliseconds} ms, freshness: {string.Join(",", baselines.Values.Select(b => b.Freshness).Distinct())}");
sw.Restart(); await provider.GetWeatherAsync(hubs); Console.WriteLine($"2nd weather call (cache): {sw.ElapsedMilliseconds} ms");

var calc = new WeatherStatisticsCalculator(new WeatherThresholds());
var denver = weather["denver"];
var y2025 = calc.Summarize(denver.Days, new DateOnly(2025,1,1), new DateOnly(2025,12,31));
Console.WriteLine($"Denver 2025: {y2025.SnowDays} snow days of {y2025.DaysObserved} = {y2025.PercentOfDays(y2025.SnowDays):F1}%");

var settings = new ScoringSettings();
var engine = new RiskScoringEngine(HazardScorers.CreateDefault(settings, new WeatherThresholds()), settings);
Console.WriteLine();
Console.WriteLine("hub            comp  rating     conf   | winter hurr  flood storm heat | drivers");
foreach (var s in hubs.Select(h => engine.Score(new HubHazardInputs(h,
             calc.Summarize(weather[h.Id].Days, provider.Window.From, provider.Window.To),
             baselines[h.CountyFips].Baseline))).OrderByDescending(s => s.CompositeScore))
{
    string hz(HazardType t) => s.For(t).Detail.Score.ToString("F0").PadLeft(5);
    Console.WriteLine($"{s.Hub.Id,-14} {s.CompositeScore,5:F1} {s.Rating,-10} {s.Confidence,-6} | {hz(HazardType.Winter)} {hz(HazardType.Hurricane)} {hz(HazardType.Flood)} {hz(HazardType.SevereStorm)} {hz(HazardType.Heat)} | {string.Join(",", s.TopDrivers)}");
}
var dallas = baselines["48113"].Baseline!;
Console.WriteLine($"\nDallas NRI percentiles: winter {dallas.WinterWeather} ice {dallas.IceStorm} tornado {dallas.Tornado} hail {dallas.Hail} heat {dallas.HeatWave} hurricane {dallas.Hurricane}");
