public void Hurricane_BothSignals_BaselineDominates()
{
    var scorer = new HurricaneScorer(Settings, Thresholds);

    // 4 days → 1/yr → 1/3 = 33.33.  Score = 0.25×33.33 + 0.75×90 = 75.83 → 75.8 → Very High.
