    Assert.Equal(RiskRating.VeryHigh, s.Rating);
    Assert.Contains(s.Factors, f => f is { Name: "tropicalStormGustDaysPerYear", Value: 1.0 });
    Assert.Contains(s.Factors, f => f is { Name: "nriHurricane", Value: 90.0 });
}

