  $b = "http://localhost:5050"
  "== Q1: Midwest winter =="
  $sw = [Diagnostics.Stopwatch]::StartNew(); $r = Invoke-RestMethod "$b/api/risk/rankings?region=Midwest&hazard=Winter"; $ms = $sw.ElapsedMilliseconds
  $r.entries | ForEach-Object { "  #$($_.rank) $($_.hubId) winter=$($_.score) ($($_.rating)) composite=$($_.compositeScore) data=$($_.weatherFreshness)/$($_.baselineFreshness)" }; "  ($ms ms)"
  "== Q2: Miami vs Houston hurricane+flood =="
  $c = Invoke-RestMethod "$b/api/risk/compare?hubs=miami,houston&hazards=Hurricane&hazards=Flood"
  $c.rows | ForEach-Object { "  $($_.metric): " + (($_.values | ForEach-Object { "$($_.hubId)=$($_.score)" }) -join ' ') + " -> most exposed $($_.mostExposedHubId) (spread $($_.spread))" }
  "== Q3: Denver snow last year =="
  $w = Invoke-RestMethod "$b/api/hubs/denver/weather"; $s = $w.disruptionDays | Where-Object metric -eq 'snowDays'
  "  $($w.from)..$($w.to): $($s.days) snow days of $($w.daysObserved) = $($s.percentOfDays)% ($($s.definition)); total snowfall $($w.totals.totalSnowfallCm) cm"
  "== Q4: Why is Dallas high =="
  $sw.Restart(); $d = Invoke-RestMethod "$b/api/hubs/dallas/risk"; $ms = $sw.ElapsedMilliseconds
  "  composite $($d.compositeScore) $($d.rating), confidence $($d.confidence), drivers: $($d.topDrivers -join ', ') ($ms ms)"
  $d.hazards | ForEach-Object { "  $($_.hazard): score $($_.score) obs=$($_.observedScore) base=$($_.baselineScore) contrib=$($_.contribution)" + $(if ($_.isWorstHazard) {' [worst]'}) }
  "  evidence (severe storm): " + (($d.hazards | Where-Object hazard -eq 'SevereStorm').evidence | ForEach-Object { "$($_.name)=$($_.value)" }) -join ', '
  "== errors =="
  try { Invoke-RestMethod "$b/api/hubs/gotham/risk" } catch { "  404 ok: " + $_.ErrorDetails.Message.Substring(0,90) }
} finally { Stop-Process -Id $p.Id -Force; Get-Process -Name WeatherRisk.Api -ErrorAction SilentlyContinue | Stop-Process -Force }

