$log = Join-Path $env:TEMP "wr-api.log"
$p = Start-Process dotnet -ArgumentList 'run','--project','src/WeatherRisk.Api','--launch-profile','http','--no-build' -PassThru -WindowStyle Hidden -RedirectStandardOutput $log
try {
  for ($i=0; $i -lt 40; $i++) { Start-Sleep 2; try { Invoke-RestMethod http://localhost:5050/api/system/health -ErrorAction Stop | Out-Null; break } catch {} }
  function Ask($q, $conv) {
    $b = @{ message = $q }; if ($conv) { $b.conversationId = $conv }
    $r = Invoke-RestMethod http://localhost:5050/api/chat -Method Post -ContentType application/json -Body ($b | ConvertTo-Json) -TimeoutSec 120
    "`n### Q: $q"
    "[$($r.llm.model) steps=$($r.llm.steps) $($r.llm.durationMs)ms | tools: $(($r.toolCalls | ForEach-Object { $_.tool }) -join ',') | grounded=$($r.verification.allFindingsGrounded) $($r.verification.notes -join '; ')]"
    $r.answer
    return $r.conversationId
  }
  $c = Ask "Why is the Dallas hub's weather disruption risk high?" $null
  $null = Ask "And how does it compare with Houston on those drivers?" $c
  $null = Ask "What percentage of days in Denver last year had snowfall?" $null
  $null = Ask "Compare Miami and Houston in terms of hurricane and flood exposure." $null
  $null = Ask "What's the capital of France?" $null
} catch { "FAILED: $($_.Exception.Message) $($_.ErrorDetails.Message)" }
finally { Stop-Process -Id $p.Id -Force; Get-Process -Name WeatherRisk.Api -ErrorAction SilentlyContinue | Stop-Process -Force }
