/// </code>
/// The LLM decides <i>what</i> to look up and how to explain it; all numbers come from the deterministic
/// tools, and the final answer is schema-validated and grounding-checked before it reaches the analyst.
/// </summary>
/// <remarks>
/// Scoped (tools use the scoped <see cref="HubRiskService"/>). Tool calls within a step run sequentially because
/// they share one DbContext; they are fast (cache-backed) compared with the LLM round-trip.
/// </remarks>
public sealed class ChatAgent
{
    // One schema-repair attempt is usually enough; more just burns the step budget.
    private const int MaxInvalidAnswers = 2;

    private static readonly LlmToolDefinition SubmitAnswerDefinition = new(
        AgentPrompt.SubmitAnswerTool,
        "Submit the final structured answer. Call exactly once, after gathering facts with the other tools.",
        AgentJson.SchemaFor<AgentAnswer>());

    private readonly ILlmClient _llm;
    private readonly Dictionary<string, IAgentTool> _tools;
    private readonly IReadOnlyList<LlmToolDefinition> _definitions;
    private readonly HubRiskService _service;
    private readonly IConversationStore _conversations;
    private readonly AgentSettings _settings;
    private readonly TimeProvider _time;

    /// <summary>Creates the agent.</summary>
    /// <param name="llm">LLM port (with provider fallback behind it).</param>
    /// <param name="tools">Available tools.</param>
    /// <param name="service">Application service (hub catalog and window for the prompt).</param>
    /// <param name="conversations">Conversation memory.</param>
    /// <param name="settings">Turn limits.</param>
    /// <param name="time">Clock.</param>
    public ChatAgent(
        ILlmClient llm,
        IEnumerable<IAgentTool> tools,
        HubRiskService service,
        IConversationStore conversations,
        AgentSettings settings,
        TimeProvider time)
    {
        _llm = llm;
        _tools = tools.ToDictionary(t => t.Definition.Name, StringComparer.Ordinal);
        _definitions = [.. _tools.Values.Select(t => t.Definition), SubmitAnswerDefinition];
        _service = service;
        _conversations = conversations;
        _settings = settings;
        _time = time;
    }

    /// <summary>Answers one question, continuing a conversation when an id is given.</summary>
    /// <param name="message">The analyst's question.</param>
    /// <param name="conversationId">Existing conversation id, or null to start a new one.</param>
    /// <param name="cancellationToken">Request cancellation.</param>
    /// <returns>Validated answer with audit trail.</returns>
    /// <exception cref="RequestValidationException">When the message is empty or too long.</exception>
    /// <exception cref="LlmUnavailableException">When no LLM provider could answer.</exception>
    /// <exception cref="AgentFailedException">When no valid answer was produced within the step budget or deadline.</exception>
    public async Task<ChatResult> AskAsync(string message, string? conversationId, CancellationToken cancellationToken = default)
    {
        message = message?.Trim() ?? string.Empty;
        if (message.Length == 0 || message.Length > _settings.MaxMessageLength)
        {
            throw new RequestValidationException($"'message' must be 1-{_settings.MaxMessageLength} characters.");
        }

        string id = string.IsNullOrWhiteSpace(conversationId) ? Guid.NewGuid().ToString("N") : conversationId.Trim();
        long started = Stopwatch.GetTimestamp();

        using var deadline = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        deadline.CancelAfter(TimeSpan.FromSeconds(_settings.TimeoutSeconds));

        try
        {
            List<LlmMessage> messages = await BuildMessagesAsync(id, message, deadline.Token);
            return await RunLoopAsync(id, message, messages, started, deadline.Token);
        }
        catch (OperationCanceledException) when (!cancellationToken.IsCancellationRequested)
        {
            throw new AgentFailedException($"The assistant did not finish within {_settings.TimeoutSeconds} seconds.");
        }
    }

    /// <summary>System prompt + recent history + the new question.</summary>
    private async Task<List<LlmMessage>> BuildMessagesAsync(string conversationId, string message, CancellationToken cancellationToken)
    {
        IReadOnlyList<Hub> hubs = await _service.GetHubsAsync(cancellationToken: cancellationToken);
        IReadOnlyList<ConversationTurn> history = await _conversations.GetAsync(conversationId, cancellationToken);

        var messages = new List<LlmMessage>(2 + (2 * _settings.HistoryTurns) + 8)
        {
            LlmMessage.System(AgentPrompt.Build(hubs, _service.Window, DateOnly.FromDateTime(_time.GetUtcNow().UtcDateTime))),
        };

        foreach (ConversationTurn turn in history.TakeLast(_settings.HistoryTurns))
        {
            messages.Add(LlmMessage.User(turn.UserMessage));
            messages.Add(LlmMessage.Assistant(turn.AssistantAnswer));
        }

        messages.Add(LlmMessage.User(message));
        return messages;
    }

    private async Task<ChatResult> RunLoopAsync(
        string conversationId, string message, List<LlmMessage> messages, long started, CancellationToken cancellationToken)
    {
        var evidence = new AnswerValidator.ToolEvidence();
        var trace = new List<ToolCallTrace>();
        int promptTokens = 0, completionTokens = 0, invalidAnswers = 0;

        for (int step = 1; step <= _settings.MaxSteps; step++)
        {
            LlmCompletion completion = await _llm.CompleteAsync(new LlmRequest(messages, _definitions, RequireToolCall: true), cancellationToken);
            promptTokens += completion.PromptTokens;
            completionTokens += completion.CompletionTokens;

            if (completion.ToolCalls.Count == 0)
            {
                // The model answered in prose despite tool_choice=required — remind it of the contract.
                messages.Add(LlmMessage.Assistant(completion.Content));
                messages.Add(LlmMessage.User($"Reply by calling {AgentPrompt.SubmitAnswerTool} with the structured answer."));
                continue;
            }

            messages.Add(LlmMessage.Assistant(completion.Content, completion.ToolCalls));
            foreach (LlmToolCall call in completion.ToolCalls)
            {
                if (call.Name == AgentPrompt.SubmitAnswerTool)
                {
                    if (AnswerValidator.TryParse(call.ArgumentsJson, out AgentAnswer? parsed, out string? error))
                    {
                        AgentAnswer answer = parsed! with { Answer = AnswerCleaner.RemoveDuplicatedSections(parsed.Answer) };
                        GroundingReport grounding = AnswerValidator.Ground(answer, evidence);
                        await _conversations.AppendAsync(
                            conversationId, new ConversationTurn(message, answer!.Answer, _time.GetUtcNow()), cancellationToken);
                        return new ChatResult(
                            conversationId, answer, grounding, trace, completion.Provider, completion.Model, step,
                            promptTokens, completionTokens, Stopwatch.GetElapsedTime(started));
                    }

                    if (++invalidAnswers > MaxInvalidAnswers)
                    {
                        throw new AgentFailedException($"The assistant returned an invalid answer: {error}");
                    }

                    messages.Add(LlmMessage.Tool(call.Id, $"{{\"error\":{System.Text.Json.JsonSerializer.Serialize(error)}}}"));
                    continue;
                }

                messages.Add(LlmMessage.Tool(call.Id, await RunToolAsync(call, evidence, trace, cancellationToken)));
            }
        }

        throw new AgentFailedException($"The assistant did not produce an answer within {_settings.MaxSteps} steps.");
    }

    /// <summary>Executes one tool call, recording evidence for grounding and a trace entry.</summary>
    private async Task<string> RunToolAsync(
        LlmToolCall call, AnswerValidator.ToolEvidence evidence, List<ToolCallTrace> trace, CancellationToken cancellationToken)
    {
        long start = Stopwatch.GetTimestamp();
        if (!_tools.TryGetValue(call.Name, out IAgentTool? tool))
        {
            trace.Add(new ToolCallTrace(call.Name, call.ArgumentsJson, false, Stopwatch.GetElapsedTime(start)));
            return $"{{\"error\":\"Unknown tool '{call.Name}'. Available: {string.Join(", ", _tools.Keys)}, {AgentPrompt.SubmitAnswerTool}.\"}}";
        }

        ToolResult result = await tool.InvokeAsync(call.ArgumentsJson, cancellationToken);
        if (result.Succeeded)
        {
            AnswerValidator.Collect(result.Json, evidence);
        }

        trace.Add(new ToolCallTrace(call.Name, call.ArgumentsJson, result.Succeeded, Stopwatch.GetElapsedTime(start)));
        return result.Json;
    }
}

using System.Globalization;
using System.Text.Json;
using System.Text.RegularExpressions;

namespace WeatherRisk.Eval.Checks;

/// <summary>
/// Evaluates checks on an agent's <c>/api/chat</c> response. Expected values are resolved from the
/// deterministic API at run time, so cases stay valid when the underlying data is refreshed.
/// </summary>
internal static partial class AgentCheckEvaluator
{
    private const double DefaultTolerance = 0.06;

    /// <summary>Evaluates one check.</summary>
    /// <param name="check">The check.</param>
    /// <param name="response">Chat response JSON.</param>
    /// <param name="api">Ground-truth reader.</param>
    /// <param name="cancellationToken">Cancellation token.</param>
    /// <returns>Pass/fail with detail.</returns>
    public static async Task<CheckResult> EvaluateAsync(
        AgentCheck check, JsonElement response, IApiReader api, CancellationToken cancellationToken)
    {
        string answer = Str(response, "answer");
        try
        {
            return check.Type switch
            {
                "intent" => Intent(check, response),
                "toolCalled" => ToolCalled(check, response),
                "noToolCalls" => NoToolCalls(response),
                "grounded" => Grounded(check, response),
                "mentionsHubs" => MentionsAll($"mentionsHubs", answer, check.Hubs ?? []),
                "mentionsText" => MentionsAny(answer, check.AnyOf ?? []),
                "mentionsTopRanked" => await MentionsTopRankedAsync(check, answer, api, cancellationToken),
                "citesApiValue" => await CitesApiValueAsync(check, response, answer, api, cancellationToken),
                "mentionsApiText" => await MentionsApiTextAsync(check, answer, api, cancellationToken),
                _ => CheckResult.Fail(check.Type, $"unknown check type '{check.Type}'"),
            };
        }
        catch (Exception ex) when (ex is KeyNotFoundException or HttpRequestException or FormatException or InvalidOperationException)
        {
            return CheckResult.Fail(check.Type, ex.Message);
        }
    }

    private static CheckResult Intent(AgentCheck check, JsonElement response)
    {
        string intent = Str(response, "intent");
        IReadOnlyList<string> accepted = check.AnyOf ?? [];
        return accepted.Contains(intent, StringComparer.OrdinalIgnoreCase)
            ? CheckResult.Pass("intent", intent)
            : CheckResult.Fail("intent", $"expected one of [{string.Join(", ", accepted)}], actual {intent}");
    }

    private static CheckResult ToolCalled(AgentCheck check, JsonElement response)
    {
        string name = $"toolCalled({check.Tool})";
        List<JsonElement> calls = response.GetProperty("toolCalls").EnumerateArray()
            .Where(c => Str(c, "tool") == check.Tool && c.GetProperty("succeeded").GetBoolean())
            .ToList();
        if (calls.Count == 0)
        {
            return CheckResult.Fail(name, $"not called successfully; calls: {ToolList(response)}");
        }

        if (check.Args is not { ValueKind: JsonValueKind.Object } expected)
        {
            return CheckResult.Pass(name, ToolList(response));
        }

        return calls.Any(c => ArgsMatch(expected, c.GetProperty("arguments")))
            ? CheckResult.Pass(name, $"args ⊇ {expected.GetRawText()}")
            : CheckResult.Fail(name, $"expected args ⊇ {expected.GetRawText()}, got {string.Join(" | ", calls.Select(c => c.GetProperty("arguments").GetRawText()))}");
    }

    /// <summary>Every expected property must be present with an equal value; arrays compare as sets (case-insensitive).</summary>
    internal static bool ArgsMatch(JsonElement expected, JsonElement actual)
    {
        if (actual.ValueKind != JsonValueKind.Object)
        {
            return false;
        }

        foreach (JsonProperty property in expected.EnumerateObject())
        {
            JsonElement value = actual.EnumerateObject()
                .FirstOrDefault(p => string.Equals(p.Name, property.Name, StringComparison.OrdinalIgnoreCase)).Value;
            if (value.ValueKind == JsonValueKind.Undefined)
            {
                return false;
            }

            bool equal = property.Value.ValueKind == JsonValueKind.Array && value.ValueKind == JsonValueKind.Array
                ? new HashSet<string>(property.Value.EnumerateArray().Select(JsonPath.Text), StringComparer.OrdinalIgnoreCase)
                    .SetEquals(value.EnumerateArray().Select(JsonPath.Text))
                : ModelCheckEvaluator.Same(JsonPath.Text(value), JsonPath.Text(property.Value));
            if (!equal)
            {
                return false;
            }
        }

        return true;
    }

    private static CheckResult NoToolCalls(JsonElement response) =>
        response.GetProperty("toolCalls").GetArrayLength() == 0
            ? CheckResult.Pass("noToolCalls", "no tools called")
            : CheckResult.Fail("noToolCalls", $"called: {ToolList(response)}");

    private static CheckResult Grounded(AgentCheck check, JsonElement response)
    {
        bool grounded = response.GetProperty("verification").GetProperty("allFindingsGrounded").GetBoolean();
        int findings = response.GetProperty("findings").GetArrayLength();
        int minimum = check.Count ?? 0;
        string detail = $"{findings} findings, all grounded = {grounded}";
        return grounded && findings >= minimum
            ? CheckResult.Pass("grounded", detail)
            : CheckResult.Fail("grounded", $"{detail} (need ≥ {minimum}); notes: {string.Join("; ", response.GetProperty("verification").GetProperty("notes").EnumerateArray().Select(n => n.GetString()))}");
    }

    private static CheckResult MentionsAll(string name, string answer, IReadOnlyList<string> phrases)
    {
        List<string> missing = phrases.Where(p => !answer.Contains(p, StringComparison.OrdinalIgnoreCase)).ToList();
        return missing.Count == 0
            ? CheckResult.Pass(name, $"mentions {string.Join(", ", phrases)}")
            : CheckResult.Fail(name, $"missing: {string.Join(", ", missing)}");
    }

    private static CheckResult MentionsAny(string answer, IReadOnlyList<string> phrases)
    {
        string? found = phrases.FirstOrDefault(p => answer.Contains(p, StringComparison.OrdinalIgnoreCase));
        return found is not null
            ? CheckResult.Pass("mentionsText", $"found '{found}'")
            : CheckResult.Fail("mentionsText", $"none of [{string.Join(", ", phrases)}] in answer");
    }

    private static async Task<CheckResult> MentionsTopRankedAsync(
        AgentCheck check, string answer, IApiReader api, CancellationToken cancellationToken)
    {
        int count = check.Count ?? 1;
        JsonElement ranking = await api.GetAsync($"/api/risk/rankings?{check.Query}", cancellationToken);
        List<string> expected = ranking.GetProperty("entries").EnumerateArray().Take(count)
            .Select(e => Str(e, "hubName").Replace(" Hub", string.Empty, StringComparison.Ordinal))
            .ToList();
        return MentionsAll($"mentionsTopRanked({check.Query}, {count})", answer, expected);
    }

    private static async Task<CheckResult> CitesApiValueAsync(
        AgentCheck check, JsonElement response, string answer, IApiReader api, CancellationToken cancellationToken)
    {
        string name = $"citesApiValue({check.Path})";
        JsonElement truth = JsonPath.Single(await api.GetAsync(check.Url!, cancellationToken), check.Path!);
        double expected = truth.GetDouble();
        double tolerance = check.Tolerance ?? DefaultTolerance;

        IEnumerable<double> cited = response.GetProperty("findings").EnumerateArray().Select(f => f.GetProperty("value").GetDouble())
            .Concat(NumberPattern().Matches(answer).Select(m => double.Parse(m.Value, CultureInfo.InvariantCulture)));
        return cited.Any(v => Math.Abs(v - expected) <= tolerance)
            ? CheckResult.Pass(name, $"cites {expected}")
            : CheckResult.Fail(name, $"expected {expected} (±{tolerance}) in findings or answer");
    }

    private static async Task<CheckResult> MentionsApiTextAsync(
        AgentCheck check, string answer, IApiReader api, CancellationToken cancellationToken)
    {
        string value = JsonPath.Text(JsonPath.Single(await api.GetAsync(check.Url!, cancellationToken), check.Path!));
        string humanized = Humanize(value); // "SevereStorm" may be written "severe storm".
        bool found = answer.Contains(value, StringComparison.OrdinalIgnoreCase)
                     || answer.Contains(humanized, StringComparison.OrdinalIgnoreCase);
        return found
            ? CheckResult.Pass($"mentionsApiText({check.Path})", $"mentions {value}")
            : CheckResult.Fail($"mentionsApiText({check.Path})", $"'{value}' not in answer");
    }

    internal static string Humanize(string identifier) => PascalBoundary().Replace(identifier, "$1 $2");

    private static string Str(JsonElement element, string property) =>
        element.TryGetProperty(property, out JsonElement value) && value.ValueKind == JsonValueKind.String ? value.GetString()! : string.Empty;

    private static string ToolList(JsonElement response) =>
        string.Join(", ", response.GetProperty("toolCalls").EnumerateArray().Select(c => Str(c, "tool"))) is { Length: > 0 } list ? list : "(none)";

    [GeneratedRegex(@"-?\d+(?:\.\d+)?")]
    private static partial Regex NumberPattern();

    [GeneratedRegex("([a-z])([A-Z])")]
    private static partial Regex PascalBoundary();
}

