$backup = Join-Path $env:TEMP "wr-appdata-backup"; if (Test-Path $backup) { Remove-Item $backup -Recurse -Force }
if (Test-Path src/WeatherRisk.Api/App_Data) { Move-Item src/WeatherRisk.Api/App_Data $backup }
"fresh DB: " + (-not (Test-Path src/WeatherRisk.Api/App_Data))
$sw = [Diagnostics.Stopwatch]::StartNew()
$p = Start-Process dotnet -ArgumentList 'run','--project','src/WeatherRisk.Api','--launch-profile','http','--no-build' -PassThru -WindowStyle Hidden
$b = "http://localhost:5050"
try {
  for ($i=0; $i -lt 60; $i++) { Start-Sleep 1; try { Invoke-RestMethod "$b/api/system/health" -ErrorAction Stop | Out-Null; break } catch {} }
  "app up after $([int]$sw.Elapsed.TotalSeconds)s (migrations applied, warm-up running in background)"
  for ($i=0; $i -lt 60; $i++) { Start-Sleep 3; $m = Invoke-RestMethod "$b/api/system/metrics"; $om = $m.dependencies | Where-Object dependency -eq 'open-meteo'; $fe = $m.dependencies | Where-Object dependency -eq 'fema-nri'
    if ($om.succeeded -ge 15 -and $fe.succeeded -ge 1) { break } }
  "warm-up: open-meteo ok=$($om.succeeded) failed=$($om.failed) | fema ok=$($fe.succeeded) failed=$($fe.failed) | after $([int]$sw.Elapsed.TotalSeconds)s"
  Start-Sleep 5   # let the last cache writes finish
  "`n--- endpoint smoke test ---"
  $checks = @(
    @("GET","/",200), @("GET","/swagger/index.html",200), @("GET","/openapi/v1.json",200), @("GET","/js/app.js",200),
    @("GET","/api/system/health",200), @("GET","/api/system/metrics",200), @("GET","/api/system/schema",200),
    @("GET","/api/hubs",200), @("GET","/api/hubs?region=Midwest",200), @("GET","/api/hubs/dallas",200),
    @("GET","/api/hubs/dallas/risk",200), @("GET","/api/hubs/denver/weather",200), @("GET","/api/hubs/houston/weather?from=2024-01-01&to=2024-12-31",200),
    @("GET","/api/risk/rankings?region=Midwest&hazard=Winter",200), @("GET","/api/risk/compare?hubs=miami,houston&hazards=Hurricane&hazards=Flood",200),
    @("GET","/api/risk/model",200),
    @("GET","/api/hubs/gotham/risk",404), @("GET","/api/risk/rankings?hazard=Tsunami",400), @("GET","/api/hubs/denver/weather?from=2010-01-01&to=2010-12-31",400),
    @("GET","/api/risk/compare?hubs=miami",400), @("GET","/api/nope",404))
  $ok = 0
  foreach ($c in $checks) {
    try { $r = Invoke-WebRequest "$b$($c[1])" -Method $c[0] -UseBasicParsing -TimeoutSec 60; $s = [int]$r.StatusCode } catch { $s = [int]$_.Exception.Response.StatusCode }
    $pass = $s -eq $c[2]; if ($pass) { $ok++ }
    "{0} {1,-4} {2,-70} {3}" -f $(if ($pass) {"PASS"} else {"FAIL"}), $c[0], $c[1], $s
  }
  $chat = Invoke-WebRequest "$b/api/chat" -Method Post -ContentType application/json -Body '{"message":"Which hubs in the Midwest are most exposed to winter disruption?"}' -UseBasicParsing -TimeoutSec 120
  $cj = $chat.Content | ConvertFrom-Json
  $chatPass = $chat.StatusCode -eq 200 -and $cj.verification.allFindingsGrounded
  if ($chatPass) { $ok++ }
  "{0} POST /api/chat  {1}  model={2} tools={3} grounded={4} {5}ms" -f $(if ($chatPass) {"PASS"} else {"FAIL"}), $chat.StatusCode, $cj.llm.model, ($cj.toolCalls.tool -join ','), $cj.verification.allFindingsGrounded, $cj.llm.durationMs
  $bad = try { Invoke-WebRequest "$b/api/chat" -Method Post -ContentType application/json -Body '{"message":""}' -UseBasicParsing; 200 } catch { [int]$_.Exception.Response.StatusCode }
  if ($bad -eq 400) { $ok++ }; "{0} POST /api/chat (empty message) {1}" -f $(if ($bad -eq 400) {"PASS"} else {"FAIL"}), $bad
  "`nsmoke: $ok/$($checks.Count + 2) passed"
  $h = Invoke-RestMethod "$b/api/system/health"; "health: $($h.status) | " + (($h.checks | ForEach-Object { "$($_.name)=$($_.status)" }) -join ', ')
  $rk = Invoke-RestMethod "$b/api/risk/rankings"; "confidence of all 15 hubs: " + (($rk.entries.confidence | Group-Object | ForEach-Object { "$($_.Name)=$($_.Count)" }) -join ', ')
} finally { Stop-Process -Id $p.Id -Force; Get-Process -Name WeatherRisk.Api -ErrorAction SilentlyContinue | Stop-Process -Force }

